// Compute rounded thresholds using REAL (binary32) arithmetic.
span := hiLevel - loLevel;
hiRelease := hiLevel - hystWindow;
loRelease := loLevel + hystWindow;

// Default error clear for this scan.
error := FALSE;
status := 0;

IF loLevel >= hiLevel THEN
    error := TRUE;
    status := 16#8001;
    // preserve hiAlarmState and loAlarmState (no updates)
ELSIF hystWindow >= span THEN
    error := TRUE;
    status := 16#8002;
    // preserve alarms
